Method.Source:
protected void init()
{
    api = XAPI_APIS::GetBusRelExpectedConsumption;
    super();
}

protected void postRun()
{
    EGS_API_DataContract_Response res;

    if (!responseText)
    {
        return;
    }

    res = FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response), responseText);

    if (status == XAPI_APIStatus::Error)
    {
        return;
    }

    if (res.parmStatus() && strLwr(res.parmStatus()) != 'ok')
    {
        status       = XAPI_APIStatus::Error;
        errorMessage = res.parmMessage();
        return;
    }

    logKey   = "BusRelExpectedConsumption";
    logValue = res.parmMessage();
}

protected str body()
{
    CustTable       custTable;
    smmBusRelTable  busRelTable;
    str             custAccount;
    Map             configMap;

    custAccount = XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, 'CustAccount');
    custTable   = CustTable::find(custAccount);

    select firstonly BusRelAccount from busRelTable
        where busRelTable.Party == custTable.Party;

    configMap = new Map(Types::String, Types::String);
    configMap.insert('<BusRelAccount>', busRelTable.BusRelAccount);

    return this.prepareBody(configMap);
}
